mapper.sql:
 		from product as a
 		left join discount b on b.dc_id = a.discount_dc_id
 		where 1=1
		AND a.pd_use = #{shUseNy}
         AND 0 = #{shDelNy}
         AND a.local = #{shlocal}
         AND a.type = #{shtype}
         AND a.brand = #{shbrand}


			AND a.pd_regiDate BETWEEN #{shDateStart} AND #{shDateEnd}
			AND a.pd_modiDate  BETWEEN #{shDateStart} AND #{shDateEnd}



            AND b.cg_id = #{shValue}
            AND b.cg_name LIKE CONCAT('%',#{shValue},'%')
            AND a.cd_name LIKE CONCAT('%',#{shValue},'%')
